import{z as l,x as o,o as A,c as s,q as B,j as r,D as a,d as t,s as n,S as i}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"程序化交易的报备实践","description":"","frontmatter":{"title":"程序化交易的报备实践","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/cn-programmatic-filing.md","filePath":"quant/cn-programmatic-filing.md","lastUpdated":1791063341000}'),d={name:"quant/cn-programmatic-filing.md"};function c(D,E,p,m,C,F){const e=o("Mermaid");return A(),s("div",null,[E[2]||(E[2]=B('<h1 id="程序化交易的报备实践" tabindex="-1">程序化交易的报备实践 <a class="header-anchor" href="#程序化交易的报备实践" aria-label="Permalink to &quot;程序化交易的报备实践&quot;">​</a></h1><div class="epigraph"><p>报备档案是交易所给账户画的肖像：监控跑在申报与成交数据上，画像和真人长期对不上，系统不会先问你是不是忘了更新。</p><footer>—— 据证监会程序化交易管理规定及交易所报备通知口径整理</footer></div><p><a href="/quant/cn-margin-lending-structure">上一课</a>把空头腿的券源工程立住，工具与约束单元走到第三件：交易身份本身。<a href="/quant/cn-program-trading-rules">程序化交易管理规定与实施细则</a>已写制度框架，<a href="/quant/cn-amac-program-trading">中基协程序化交易自律要求</a>写了私募侧自律口径，<a href="/quant/cn-hft-threshold">高频交易认定标准</a>写了速率认定。本课写实务操作：报备什么、通过谁报、变更怎么跟、报备信息如何与交易所的监控数据互相勾稽。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>报备在实践里常被当成一次性开户材料，错在这里。它是一份持续有效的技术档案：策略从低频改成日内、系统从外购换成自研、服务器从本地搬进托管机房、速率长到认定线以上，每一项都触发更新义务；多券商开户时同一套策略要在每家分别报备，口径不一致会在监控侧留下两个不同的「你」。<span class="marginnote">可以把它想象成你的「交易简历」：交易所按简历设定对你账户的预期，实际报撤数据就是日常考勤。简历写的是慢跑，考勤却是百米冲刺，系统不会先问你是不是忘了改简历——它按数据处置。所以每次「换了跑法」都要同步改简历。</span>报备画像与实际交易特征长期偏离，轻则被要求补报整改，重则在异常交易处置里处于不利位置——而策略团队往往是最晚知道画像过期的人。</p>',5)),(A(),r(i,null,{default:a(()=>[n(e,{id:"mermaid-13",class:"mermaid",graph:"flowchart%20TD%0A%20%20EV1%5B%22%E7%AD%96%E7%95%A5%E4%BD%8E%E9%A2%91%E6%94%B9%E6%97%A5%E5%86%85%22%5D%20--%3E%20UPD%5B%22%E8%A7%A6%E5%8F%91%E5%8F%98%E6%9B%B4%E6%9B%B4%E6%96%B0%22%5D%0A%20%20EV2%5B%22%E7%B3%BB%E7%BB%9F%E5%A4%96%E8%B4%AD%E6%8D%A2%E8%87%AA%E7%A0%94%22%5D%20--%3E%20UPD%0A%20%20EV3%5B%22%E6%9C%8D%E5%8A%A1%E5%99%A8%E6%90%AC%E5%85%A5%E6%89%98%E7%AE%A1%E6%9C%BA%E6%88%BF%22%5D%20--%3E%20UPD%0A%20%20EV4%5B%22%E9%80%9F%E7%8E%87%E8%B6%8A%E8%BF%87%E8%AE%A4%E5%AE%9A%E7%BA%BF%22%5D%20--%3E%20UPD%0A%20%20UPD%20--%3E%20WHO%7B%22%E5%93%AA%E4%B8%AA%E8%B4%A6%E6%88%B7%3F%22%7D%0A%20%20WHO%20--%3E%7C%22%E5%8D%95%E5%88%B8%E5%95%86%22%7C%20ONE%5B%22%E7%BB%8F%E8%AF%A5%E5%BC%80%E6%88%B7%E5%88%B8%E5%95%86%E6%94%B9%E6%8A%A5%22%5D%0A%20%20WHO%20--%3E%7C%22%E5%A4%9A%E5%88%B8%E5%95%86%22%7C%20MANY%5B%22%E6%AF%8F%E5%AE%B6%E5%BC%80%E6%88%B7%E5%88%B8%E5%95%86%E5%88%86%E5%88%AB%E6%94%B9%E6%8A%A5%22%5D%0A%20%20MANY%20--%3E%20CONS%7B%22%E5%90%84%E7%AB%AF%E5%8F%A3%E5%BE%84%E4%B8%80%E8%87%B4%3F%22%7D%0A%20%20CONS%20--%3E%7C%22%E5%90%A6%22%7C%20RISK%5B%22%E7%9B%91%E6%8E%A7%E4%BE%A7%E7%94%BB%E5%83%8F%E5%88%86%E8%A3%82%22%5D%0A%20%20CONS%20--%3E%7C%22%E6%98%AF%22%7C%20OK%5B%22%E7%94%BB%E5%83%8F%E4%B8%8E%E5%AE%9E%E9%99%85%E5%AF%B9%E9%BD%90%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[t(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=B('<h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>把报备做成台账治理。字段至少含四类：账户与产品信息；策略类型与换手画像；交易系统（自研或外购及版本）与技术信息（服务器与托管位置、下单方式）；速率类指标——最高申报速率、日均申报与撤单量级——加联系人与应急安排。<span class="marginnote">术语翻译：所谓「速率类指标」，就是给交易速度记账的几个数——最快一秒报了多少笔委托、一天总共报和撤了多少笔。它们决定你的账户被归进哪个监管档位；同样的策略，把拆单从每秒几笔提到几十笔，日均申报量涨一个数量级，画像就必须改报。</span>流程三条：新账户先报备、后启用程序化；重大变更在规定时限内经开户券商更新；达到高频认定标准的，额外报告义务与差异化收费监控直接挂钩（<a href="/quant/cn-fee-cancel-ratio">差异化收费与撤单率监控</a>）。托管机房的申请信息要与报备台账能互相对上（<a href="/quant/cn-colocation-rectify">主机托管清退与交易单元整改</a>）。台账与策略版本库联动：任何改变速率画像的上线动作，先过台账、再过生产。</p>',2)),(A(),r(i,null,{default:a(()=>[n(e,{id:"mermaid-20",class:"mermaid",graph:"flowchart%20TD%0A%20%20STRAT%5B%22%E7%AD%96%E7%95%A5%E4%B8%8A%E7%BA%BF%E6%88%96%E5%8F%98%E6%9B%B4%22%5D%20--%3E%20LEDGER%5B%22%E6%8A%A5%E5%A4%87%E5%8F%B0%E8%B4%A6%EF%BC%9A%E7%AD%96%E7%95%A5%2F%E7%B3%BB%E7%BB%9F%2F%E9%80%9F%E7%8E%87%22%5D%0A%20%20LEDGER%20--%3E%20BROKER%5B%22%E7%BB%8F%E5%BC%80%E6%88%B7%E5%88%B8%E5%95%86%E6%8A%A5%E9%80%81%22%5D%0A%20%20BROKER%20--%3E%20EXCH%5B%22%E4%BA%A4%E6%98%93%E6%89%80%E4%BF%A1%E6%81%AF%E5%85%B1%E4%BA%AB%22%5D%0A%20%20EXCH%20--%3E%20MON%5B%22%E7%94%B3%E6%8A%A5%E6%92%A4%E5%8D%95%E6%95%B0%E6%8D%AE%E7%9B%91%E6%8E%A7%22%5D%0A%20%20MON%20--%3E%20MATCH%7B%22%E6%8A%A5%E5%A4%87%E5%8F%A3%E5%BE%84%E4%B8%8E%E5%AE%9E%E9%99%85%E4%B8%80%E8%87%B4%3F%22%7D%0A%20%20MATCH%20--%3E%7C%22%E5%90%A6%22%7C%20FIX%5B%22%E8%A1%A5%E6%8A%A5%E6%95%B4%E6%94%B9%EF%BC%8C%E5%BF%85%E8%A6%81%E6%97%B6%E6%9A%82%E5%81%9C%22%5D%0A%20%20MATCH%20--%3E%7C%22%E6%98%AF%22%7C%20RUN%5B%22%E6%8C%81%E7%BB%AD%E8%BF%90%E8%A1%8C%22%5D%0A%20%20STRAT%20--%3E%20HFT%7B%22%E8%BE%BE%E9%AB%98%E9%A2%91%E8%AE%A4%E5%AE%9A%3F%22%7D%0A%20%20HFT%20--%3E%7C%22%E6%98%AF%22%7C%20EXTRA%5B%22%E9%A2%9D%E5%A4%96%E6%8A%A5%E5%91%8A%E4%B9%89%E5%8A%A1%2B%E5%B7%AE%E5%BC%82%E5%8C%96%E6%94%B6%E8%B4%B9%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[t(" Loading... ",-1)])]),_:1})),E[4]||(E[4]=B('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>报备为什么是数据治理而不是合规手续。异常交易监控跑在申报与成交数据上，报备档案给出「这个账户被允许是什么样」的基准；实际速率与撤单模式长期偏离基准，系统按异常处理，不看你的意图。<span class="marginnote">常见误区：把报备当成「交作业」，交完就束之高阁。实际上交易所会拿真实申报撤单数据和你报的口径持续勾稽比对，长期对不上的后果不是「态度问题批评一下」，而是补报、整改乃至按异常交易处置——受影响的是账户本身的交易权限。</span>所以多券商、多产品的一致性是治理问题：同一策略在不同券商处速率画像不同，要么是真实的差异化部署且台账能解释，要么是治理缺陷。私募与公募的报备路径不同，但台账义务同在——载体差异留给生态单元再展开。</p><p><span class="marginnote">最常翻车的一条：回测阶段的换手画像和实盘不同。回测里看着是低频的信号，实盘为了抢单把委托拆碎、撤得更勤，速率指标越过认定线，而台账还停在旧口径。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>具体报送时限、认定阈值与收费标准以当期规定与交易所细则为准，本课程不做跨期承诺。本课不写规避报备、拆分账户稀释速率的方法——那本身是红线清单的一部分。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>报备是持续技术档案：账户、策略、系统、速率四类字段，重大变更限期更新。</li><li>高频认定把速率指标与额外义务、差异化收费挂钩，速率画像要进发布检查。</li><li>报备口径与监控数据勾稽，多券商部署的一致性是治理问题不是文书问题。</li><li>出处：证监会程序化交易管理规定与交易所实施细则口径；框架细节见<a href="/quant/cn-program-trading-rules">程序化交易管理规定与实施细则</a>。</li></ul>',7))])}const u=l(d,[["render",c]]);export{_ as __pageData,u as default};
